      "rigor": "<p>歸一化信號 $x[n] = g(2n) / (2n / \\ln^2(2n))$ 的離散傅立葉變換為：</p>\n        <div class=\"math-formula\">\n          X[k] = \\sum_{n=1}^N x[n] e^{-2\\pi i k n / N}\n        </div>\n        <p>功率譜密度 $|X[k]|^2$ 在奇質數 $p$ 的頻率 $\\omega_p = 1/p$ 處呈現離散的脈衝峰，證明了奇異級數 $\\mathfrak{S}(N)$ 是具有玻爾譜（Bohr spectrum）$\\mathbb{Q} / \\mathbb{Z}$ 的概週期函數。</p>"
