          "a": "這些就是<b>優弧</b>（Major Arcs，$\\mathfrak{M}_{q,a}$）。當 $\\alpha$ 接近小模數 $q$ 的有理數 $a/q$ 時，質數指數和 $\\sum e(p \\alpha)$ 發生最為強烈的相長干涉，為哥德巴赫拆分貢獻了主要部分！"
