      "rigor": "<p>各展區展示了加法問題上兩種互補的數學視角：</p>\n        <div class=\"math-formula\">\n          $$\\text{空間 / 離散: } g(2N) = \\sum_{p < 2N} \\mathbf{1}_{\\mathbb{P}}(p)\\mathbf{1}_{\\mathbb{P}}(2N-p)$$\n          $$\\text{譜 / 連續: } g(2N) = \\int_0^1 \\left|\\sum_{p \\le 2N} e^{2\\pi i p \\theta}\\right|^2 e^{-2\\pi i (2N)\\theta} d\\theta$$\n        </div>\n        <p>數論的魅力在於能夠在空間表象（螺旋、格點）與諧波頻率（圓周弧線、傅立葉變換）之間自由切換。</p>"
