      "rigor": "<p>哥德巴赫拆分表示數的哈代-李特爾伍德漸近公式：</p>\n        <div class=\"math-formula\">\n          $$g(2N) \\sim 2 C_2 \\prod_{p \\mid N, p > 2} \\left(\\frac{p-1}{p-2}\\right) \\int_2^{2N} \\frac{dx}{\\ln(x) \\ln(2N-x)}$$\n        </div>\n        <p>因為雙生質數常數 $2 C_2 \\approx 1.3203 > 0$ 且該積分以 $\\Theta\\left(\\frac{2N}{\\ln^2(2N)}\\right)$ 發散，在漸近意義下，對於所有充分大的偶數 $2N$，哥德巴赫拆分的數量都必然趨於無窮。</p>"
